    Varint(RetainedVarint, AfterVarint),
    F64([u8; 8], usize),
    Utf8(u64, RetainedUtf8),
    Bytes(u64),
    Record(u64, u16),
    Values(u64, u16, RetainedContext),
    Varints(u64, RetainedValueRole),
    F64s(u64),
    Statements(u64, u16),
    Map(u64, u16, RetainedContext),
