      },
      fixture.expected,
    );
    assert.deepEqual(fixture.actor, {
      priority: "command",
      writerAuthority: "retained-artifact-wal",
      activeSegmentAuthority: "artifact-wal",
      leaseBefore: ["snapshot-floor", "wal-horizon", "wal-delete"],
